-- Record review provenance without changing published review text, ratings or dates.
ALTER TABLE product_reviews
  ADD COLUMN review_origin ENUM('UNKNOWN','CUSTOMER_SUBMISSION','LEGACY_IMPORT','ADMIN_ENTRY','CURATED_SEED','CONFIRMED_CUSTOMER') NOT NULL DEFAULT 'UNKNOWN',
  ADD COLUMN is_incentivized_review TINYINT(1) NULL DEFAULT NULL;

-- Preserve the archived customer-submission source, independently of purchase verification.
UPDATE product_reviews review JOIN legacy_imports imported ON imported.id = review.import_id AND imported.status = 'COMPLETE'
SET review.review_origin = 'LEGACY_IMPORT', review.updated_at = review.updated_at
WHERE review.source = 'LEGACY' AND review.legacy_id IS NOT NULL;

-- Admin-entered reviews need a recorded customer source before external syndication.
UPDATE product_reviews review JOIN audit_logs audit ON audit.entity_type = 'product_review'
  AND audit.action = 'PRODUCT_REVIEW_CREATE' AND BINARY audit.entity_id = BINARY CAST(review.id AS CHAR)
SET review.review_origin = 'ADMIN_ENTRY', review.updated_at = review.updated_at WHERE review.source = 'LIVE';

-- Exact 110 seed records from migration 024. An IP address or missing email alone
-- never establishes whether a review is seeded or customer-authored.
UPDATE product_reviews review JOIN products product ON product.id = review.product_id
